import{at as e,it as t,n,vt as r}from"./chunks/framework.DkF-bNzI.js";var i=JSON.parse(`{"title":"表结构升级","description":"","frontmatter":{},"headers":[],"relativePath":"backend/upgrade.md","filePath":"backend/upgrade.md","lastUpdated":1795283516000}`),a={name:`backend/upgrade.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="表结构升级" tabindex="-1">表结构升级 <a class="header-anchor" href="#表结构升级" aria-label="Permalink to “表结构升级”">​</a></h1><p>本页说明库的表结构如何建立与升级、什么时候要写升级脚本、脚本怎么写，以及版本与升级记录的查看方式，适用于部署人员与修改实体的后端开发者。</p><p>表结构由 ORM 按实体建出与补齐，各种库走同一条路径；升级脚本只做 ORM 做不了的事。</p><table tabindex="0"><thead><tr><th>库</th><th>建表方式</th></tr></thead><tbody><tr><td>开发库</td><td>Development 打开 <code>XiHan:Persistence:SqlSugar:InitTables</code>：每次启动按实体建缺表、加缺列（另补软删除实体的部分唯一索引），改了实体重启即生效</td></tr><tr><td>正式库</td><td>表结构升级器（<code>SchemaUpgrader</code>）在启动时执行：新库按实体建全部表；已有库先执行比台账新的升级脚本，再按实体补缺的表与列；<code>InitTables</code> 保持关闭</td></tr></tbody></table><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to “机制”">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td>按实体建表</td><td>新库建出全部已登记实体的表（含框架 Provider 的 <code>tenant_record</code>、<code>permission_grant_record</code>、<code>audit_record</code>、<code>message_translation</code>、<code>outbox_message</code>、调度与工作流的表），再补软删除实体的部分唯一索引；已有库只建缺的表、加缺的列，不改、不删已有的列。只在新库、执行了脚本或应用版本变了时做，同一版本的节点重启不再逐表核对</td></tr><tr><td>升级脚本</td><td><code>backend/src/XiHan.BasicApp.Host/Schema/&lt;版本&gt;/&lt;库类型&gt;/*.sql</code>：每个子目录是一个版本（<code>主.次.修订</code>），其下按库类型分目录（<code>postgresql</code>、<code>mysql</code>、<code>sqlserver</code>、<code>oracle</code>，测试用 <code>sqlite</code>），租户独立库的脚本在库类型目录下的 <code>tenant/</code> 里；按文件名顺序执行。目录名不是版本号、库类型写错、脚本没放进库类型目录都报错。目录可用 <code>BasicApp:Schema:Directory</code> 改（相对路径按程序目录解析），没有脚本时目录可以不存在</td></tr><tr><td>结构版本</td><td>新库登记为当前结构版本：脚本目录里最高的版本与 <code>6.0.0</code> 取大者；执行完某个版本的脚本即推进到那个版本</td></tr><tr><td>台账</td><td>每个库自己的 <code>sys_version</code>（结构版本、应用版本、是否升级中、升级节点与开始时间、最近一次失败的原因与时间）与 <code>sys_migration_history</code>（每一步的执行记录：批次、版本、脚本或 <code>orm-sync</code>、执行的 SQL、节点、成败、耗时、错误）</td></tr><tr><td>执行器</td><td>Runtime 的 <code>SchemaUpgrader</code>，租户独立库由 <code>TenantSchemas</code> 升级</td></tr></tbody></table><h3 id="执行顺序" tabindex="-1">执行顺序 <a class="header-anchor" href="#执行顺序" aria-label="Permalink to “执行顺序”">​</a></h3><ol><li>打开 <code>BasicApp:Schema:CreateDatabase</code>（开发环境打开，缺省关）时，平台库不存在即先建库（Oracle 的库是 DBA 事先建好的用户，不建）；台账两张表再按实体建好；</li><li>经台账行的条件更新抢升级锁；锁过了 <code>BasicApp:Schema:LockExpiryMinutes</code>（缺省 30 分钟）即视为持锁节点已退出，别的节点可以接手；等别的节点升级最多 <code>LockWaitMinutes</code>（缺省 10 分钟），等不到即升级失败。锁的时间取节点时钟，各节点的偏差远小于失效时间即可；</li><li>新库按实体建全部表，登记当前结构版本；已有库先执行比台账新的、本库类型的脚本（每个脚本一个事务，成功与失败都记进升级记录，失败即停），再按实体补缺的表与列（记一步 <code>orm-sync</code>）。库的结构版本比应用还新即 <code>RUNTIME_VALIDATION_004</code>（不能用旧版本的应用连新库）；</li><li>平台库升完后，在同一把锁里逐个升级已就绪的租户独立库：执行本库类型目录下 <code>tenant/</code> 里的脚本，再按租户库实体补表补列；台账在各自的库里，停用的租户也升。每个独立库升级期间另锁它自己的台账行，启动升级与维护页的重试不会同时升同一个库。</li></ol><p>一次升级（一次启动、一次 <code>schema upgrade</code> 或一次重试）在各库记下的步骤共用一个批次号；脚本记原文，按实体补表补列记实际发出的建表、加列与建索引语句。失败的原因与时间写进这个库的台账，下一次成功即清空。</p><p>平台库失败即升级失败。只有租户独立库失败时升级照样算成功，接着升下一个库，失败的库进报告的 <code>failures</code>；这个租户在升级成功之前不可用：它的调用一律 503（<code>RUNTIME_UNAVAILABLE_007</code>），健康项 <code>basicapp.schema</code> 降级，别的租户与平台照常。修好原因后在版本管理页重试即恢复。节点进入服务状态后还会把已就绪的独立库逐个核对一遍（关掉 <code>AutoUpgrade</code>、由运维先跑命令时也知道哪些库落后；启动升级记下的失败照样按台账核对，台账上还是失败或落后的保持不可用；读不到租户目录就每分钟再试，直到核对过一遍），之后每分钟复查不可用的库，别的节点重试成功之后本节点随之放行。</p><p>升级期间，已在运行的其他节点每 10 秒读一次台账，看到有节点持着没过期的锁即进入维护模式：除 <code>/health</code> 与 <code>/.well-known/</code> 外一律 503（<code>RUNTIME_UNAVAILABLE_003</code>，带 <code>Retry-After</code>）。</p><h3 id="执行时机" tabindex="-1">执行时机 <a class="header-anchor" href="#执行时机" aria-label="Permalink to “执行时机”">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>说明</th></tr></thead><tbody><tr><td>启动时</td><td><code>BasicApp:Schema:AutoUpgrade</code>（缺省 <code>true</code>）：开始监听之前执行，升完前这个节点不接请求；平台库失败即以日志 <code>Startup aborted: schema upgrade failed</code> 中断启动，只有租户独立库失败时照常启动</td></tr><tr><td>命令</td><td><code>XiHan.BasicApp.Host schema upgrade</code>：不启动应用（Feature 一启动就要读写自己的表，新库上升级要排在它们之前），执行后以 JSON 输出报告（<code>from</code>、<code>to</code>、<code>applied</code>、<code>runId</code>、<code>failures</code>）；平台库失败即非零退出，只有租户独立库失败时照样输出报告，再以失败退出；关掉 <code>AutoUpgrade</code> 时由运维先跑它再启动</td></tr><tr><td>预览</td><td><code>XiHan.BasicApp.Host schema plan</code>：不启动应用、只读，以 JSON 输出每个库要执行的脚本（带原文）、要建的表、要加的列与要建的索引，以及这次升级会不会按实体补表补列；有读不到的租户库即非零退出。发版前用新版本的程序对旧库跑一遍，再决定何时升级</td></tr></tbody></table><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend/src/XiHan.BasicApp.Host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --launch-profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Development</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plan</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend/src/XiHan.BasicApp.Host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --launch-profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Development</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span></span></code></pre></div><p>新库按「<code>schema upgrade</code>（或带 <code>AutoUpgrade</code> 启动一次）→ <code>seed [--only &lt;名,...&gt;] [--list]</code>」初始化，见<a href="./../deployment#首次初始化">部署</a>。脚本由执行器按台账执行，不要手工对库跑。</p><h3 id="租户独立库" tabindex="-1">租户独立库 <a class="header-anchor" href="#租户独立库" aria-label="Permalink to “租户独立库”">​</a></h3><p><code>tenants.initialize-database</code> 在租户的分片上建库、按实体只建租户库实体的表，并在该库的台账登记当前结构版本；之后随平台一起升级。独立库的库类型可以与平台库不同，脚本按它自己的类型取。见<a href="./multi-tenancy#开通三步">多租户 SaaS</a>。</p><h2 id="写升级脚本" tabindex="-1">写升级脚本 <a class="header-anchor" href="#写升级脚本" aria-label="Permalink to “写升级脚本”">​</a></h2><p>加表、加列、加索引都不用写脚本，ORM 会补。要写脚本的只有 ORM 做不了的：</p><ul><li>改列名、改表名（ORM 会把新名字当成新列或新表）；</li><li>改列的类型或长度，或把可空改成非空（ORM 不改已有的列）；</li><li>删列、删表、删索引；</li><li>搬数据：新列要从旧列算出来、拆表合表、给已有行回填非空字符串或日期时间列。</li></ul><p>写法：</p><ol><li>每个版本一个新目录，脚本放进各库类型的目录：<code>Schema/&lt;新版本&gt;/postgresql/0001-xxx.sql</code>、<code>…/mysql/…</code>、<code>…/sqlserver/…</code>、<code>…/oracle/…</code>，每种可能有旧库的库类型都要有一份（MySQL、SQL Server、Oracle 从 <code>6.0.1</code> 起支持，更早的版本目录只有 PostgreSQL 的）；影响租户库实体的，另在各库类型目录的 <code>tenant/</code> 里写一份。</li><li>脚本在按实体补表补列之前执行：要往新列搬数据的，在脚本里先把列加上。</li><li>写成可重复执行（先判断表、列、索引是否存在）：MySQL 与 Oracle 的 DDL 会隐式提交、回滚不了，失败后修好重跑，已执行的部分要能跳过。</li><li>Oracle 不能一次执行多条语句：语句之间用只有 <code>/</code> 的一行隔开，普通语句末尾不写分号，PL/SQL 块照常写。SQL Server 的脚本不要写 <code>GO</code>。</li></ol><div class="tip custom-block"><p class="custom-block-title">给已有行的表加列</p><p>InitTables 与升级器补列时，只能给已有行的表加可空列，或数值 / 枚举 / 布尔 / <code>Guid</code> 这类能按 CLR 缺省值回填的非可空列；非可空的字符串与日期时间列在实体里声明成可空，或者写脚本先加列并回填。</p></div><div class="tip custom-block"><p class="custom-block-title">新的唯一索引建不出来</p><p>实体或框架的表多了唯一索引时，库里已有重复数据会让建索引失败，升级即中断。按报错的表去掉重复行再启动；开发库也可以重建后重新 <code>seed</code>。</p></div><h2 id="版本与升级记录" tabindex="-1">版本与升级记录 <a class="header-anchor" href="#版本与升级记录" aria-label="Permalink to “版本与升级记录”">​</a></h2><p>Maintenance 包提供管理面（平台侧，页面在「平台管理 › 系统服务」下）：</p><table tabindex="0"><thead><tr><th>操作</th><th>权限码</th><th>说明</th></tr></thead><tbody><tr><td><code>versions.list</code> / <code>get</code></td><td><code>maintenance.versions.read</code></td><td>每个库一行（平台库为 <code>platform</code>，另加各独立库租户，按库名取）：库类型、结构状态、结构版本与应用带的版本、最近一次升级的应用版本与时间、升级锁、最近一次失败的原因；读不到的库带错误说明</td></tr><tr><td><code>versions.plan</code></td><td><code>maintenance.versions.read</code></td><td><code>GET /api/versions/{id}:plan</code>：只读预览这个库要执行的脚本、要建的表、列与索引，与 <code>schema plan</code> 同一份</td></tr><tr><td><code>versions.upgrade</code></td><td><code>maintenance.versions.upgrade</code></td><td><code>POST /api/versions/{id}:upgrade</code>：重试升级一个租户独立库，只锁这个库，别的调用不受影响；成功后这个租户恢复可用。平台库在节点启动时升级，不在这里重试（<code>MAINTENANCE_VALIDATION_007</code>）</td></tr><tr><td><code>versions.release-lock</code></td><td><code>maintenance.versions.release-lock</code></td><td><code>POST /api/versions/{id}:release-lock</code>：持锁的节点已经退出时手动释放锁，不用等它过期；锁还在指定的节点手里才释放（否则 <code>MAINTENANCE_CONFLICT_005</code>）。节点还在升级时释放会让两个节点同时改同一个库</td></tr><tr><td><code>migrations.list</code> / <code>get</code></td><td><code>maintenance.migrations.read</code></td><td>一个库的升级记录（筛选 <code>database</code> 选库，不给为平台库）：批次、版本、脚本或 <code>orm-sync</code>、节点、成败、耗时；取单条带执行的 SQL</td></tr></tbody></table><p>结构状态：</p><table tabindex="0"><thead><tr><th>状态</th><th>含义</th></tr></thead><tbody><tr><td>最新（<code>Current</code>）</td><td>结构版本等于应用带的版本</td></tr><tr><td>待升级（<code>Behind</code>）</td><td>结构版本与应用带的不同，还没有升级</td></tr><tr><td>升级中（<code>Upgrading</code>）</td><td>有节点持着没过期的升级锁</td></tr><tr><td>升级失败（<code>Failed</code>）</td><td>最近一次升级失败，台账记着原因</td></tr><tr><td>不可达（<code>Unreachable</code>）</td><td>读不到这个库的台账</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./database">数据库配置</a> · <a href="./../deployment">部署</a> · <a href="./health-observability">健康与可观测性</a></li></ul>`,31)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};